import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 270005;
    static int n, m, k, mod;
    static int[][] f = new int[19][MAXN];
    static List<Long> g = new ArrayList<>();
    static int[] popcount = new int[MAXN];

    static int modify_value(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void combine(int[] arr, int index, int y) {
        arr[index] = modify_value(arr[index] + y);
    }

    static int fast_pow(int base, int exp) {
        int res = 1;
        while (exp != 0) {
            if ((exp & 1) != 0) res = (int)((long)res * base % mod);
            base = (int)((long)base * base % mod);
            exp >>= 1;
        }
        return res;
    }

    static int[] fact = new int[MAXN], inv_fact = new int[MAXN];

    static void precompute(int n) {
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int)((long)fact[i - 1] * i % mod);
        }
        inv_fact[n] = fast_pow(fact[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv_fact[i] = (int)((long)inv_fact[i + 1] * (i + 1) % mod);
        }
    }

    static void transform(int[] arr, int size, int h) {
        for (int p = 1; p < size; p <<= 1) {
            for (int i = 0; i < size; i += p << 1) {
                for (int k = i; k < i + p; k++) {
                    combine(arr, k + p, h * arr[k]);
                }
            }
        }
    }

    static int l;
    static int[] popcountArray = new int[MAXN];

    static List<Long> multiply(List<Long> A, List<Long> B) {
        List<Long> C = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        for (int i = 0; i <= l; i++) {
            for (int j = 0; j <= l - i; j++) {
                C.set(i + j, C.get(i + j) + A.get(i) * B.get(j));
            }
        }
        for (int i = 0; i <= l; i++) {
            C.set(i, C.get(i) % mod);
        }
        return C;
    }

    static List<Long> series_power(List<Long> A, int k) {
        List<Long> C = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        C.set(0, 1L);
        while (k > 0) {
            if ((k & 1) != 0) {
                C = multiply(C, A);
            }
            A = multiply(A, A);
            k >>= 1;
        }
        return C;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        precompute(n);
        if ((n & 1) == 1) {
            System.out.println(fast_pow(k, n));
            return;
        }

        m = 1;
        while (m <= n) m <<= 1;
        l = 0;
        for (int i = 0; i < m; i++) {
            popcount[i] = Integer.bitCount(i);
        }
        precompute(m);
        for (int i = 0; i < m; i++) {
            f[popcount[i]][i] = inv_fact[i];
        }
        for (int i = 0; i < l; i++) {
            transform(f[i], m, 1);
        }
        g = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        for (int s = 0; s < m; s++) {
            for (int i = 0; i <= l; i++) {
                g.set(i, (long)f[i][s]);
            }
            g = series_power(g, k);
            for (int i = 0; i <= l; i++) {
                f[i][s] = g.get(i).intValue();
            }
        }
        transform(f[popcount[n]], m, -1);
        long result = modify_value((int)((long)fast_pow(k, n) - (long)f[popcount[n]][n] * fact[n] % mod));
        System.out.println(result);
    }

    static long modify_value(long x) {
        x %= mod;
        if (x < 0) x += mod;
        return x;
    }
}
